pub fn DoublyLinkedList(comptime T: type) type {
        return struct {
    first: ?*Node = null,
    last: ?*Node = null,
    len: usize = 0,

pub fn insertAfter(self: *@This(), node: *Node, new_node: *Node) void {
            new_node.prev = node;
            if ((node.next != null)) {
                var next_node = node.next.?;
                _ = &next_node;
                new_node.next = next_node;
                next_node.prev = new_node;
            } else {
                new_node.next = null;
                self.last = new_node;
            }
            node.next = new_node;
            self.len = (self.len + 1);
    }

pub fn insertBefore(self: *@This(), node: *Node, new_node: *Node) void {
            new_node.next = node;
            if ((node.prev != null)) {
                var prev_node = node.prev.?;
                _ = &prev_node;
                new_node.prev = prev_node;
                prev_node.next = new_node;
            } else {
                new_node.prev = null;
                self.first = new_node;
            }
            node.prev = new_node;
            self.len = (self.len + 1);
    }

pub fn concatByMoving(self: *@This(), list2: *Self) void {
            var l2_first = ((list2.first) orelse { return; });
            _ = &l2_first;
            if ((self.last != null)) {
                var l1_last = self.last.?;
                _ = &l1_last;
                l1_last.next = list2.first;
                l2_first.prev = self.last;
                self.len = (self.len + list2.len);
            } else {
                self.first = list2.first;
                self.len = list2.len;
            }
            self.last = list2.last;
            list2.first = null;
            list2.last = null;
            list2.len = 0;
    }

pub fn append(self: *@This(), new_node: *Node) void {
            if (self.last) |last| {
                _ = &last;
                _ = self.insertAfter(last, new_node);
            } else {
                _ = self.prepend(new_node);
            }
    }

pub fn prepend(self: *@This(), new_node: *Node) void {
            if (self.first) |first| {
                _ = &first;
                _ = self.insertBefore(first, new_node);
            } else {
                self.first = new_node;
                self.last = new_node;
                new_node.prev = null;
                new_node.next = null;
                self.len = 1;
            }
    }

pub fn remove(self: *@This(), node: *Node) void {
            if ((node.prev != null)) {
                var prev_node = node.prev.?;
                _ = &prev_node;
                prev_node.next = node.next;
            } else {
                self.first = node.next;
            }
            if ((node.next != null)) {
                var next_node = node.next.?;
                _ = &next_node;
                next_node.prev = node.prev;
            } else {
                self.last = node.prev;
            }
            self.len = (self.len - 1);
            _ = assert(((self.len == 0) or ((self.first != null) and (self.last != null))));
    }

pub fn pop(self: *@This()) ?*Node {
            const last = ((self.last) orelse { return null; });
            _ = self.remove(last);
            return last;
    }

pub fn popFirst(self: *@This()) ?*Node {
            const first = ((self.first) orelse { return null; });
            _ = self.remove(first);
            return first;
    }
    const Self = @This();
    pub const Node = DoublyLinkedListNode(T);
};
}

pub fn jsErrorToWriteError(e: bun.JSError) std.Io.Writer.Error {
        if ((e == error.JSTerminated)) {
            return error.WriteFailed;
        } else {
            if ((e == error.JSError)) {
                return error.WriteFailed;
            } else {
                return bun.handleOom(error.OutOfMemory);
            }
        }
}

pub fn autoFormatLabelFallback(comptime ty: type, comptime fallback: []const u8) []const u8 {
        if (comptime std.meta.hasFn(ty, "format")) {
            return "{f}";
        } else {
            return fallback;
        }
}

pub fn autoFormatLabel(comptime ty: type) []const u8 {
        return autoFormatLabelFallback(ty, "{s}");
}
